    }

    public List<String> getTags() {
        return tags;
    }

    public void setTags(List<String> tags) {
        this.tags.addAll(tags);
    }

    public List<SkillTag> getSkillTags() {
        return skillTags;
    }

    public void setSkillTags(List<SkillTag> skillTags) {
        this.skillTags.addAll(skillTags);
