	}

	@PUT
	public Response update(Article updatedArticle) {
		articleRepository.update(updatedArticle);
		return Response.noContent().build();
	}

	@DELETE
	@Path("/{id}")
	public Response delete(@PathParam("id") String id) {
		articleRepository.delete(id);
		return Response.noContent().build();
	}
}

