    @Produces(MediaType.TEXT_PLAIN)
    public String hello() {
        StringBuilder sb = new StringBuilder();
        sb.append("Those are saying hello:\n=======================\n\n");
        service.sendHello(s -> sb.append(" - ").append(s).append("\n"));
        return sb.toString();
    }

}

